/**
 * FE-054 criterion 7 (lane U-FE-049-064): a seeded corpus of hostile clipboard HTML, read through the
 * whitelist (`fragmentFromHtmlString`). Every output must hold only what the model allows: paragraphs of
 * text, marks bold, italic and link, and a link whose target matches the model's link pattern (I9). No
 * script, style, frame, object or handler reaches the output, and the text of a dropped element never does.
 *
 * The corpus is generated by fast-check with a fixed seed (54), so a failure can be replayed. It is a
 * generated corpus, not a stored one: the stored Word and Google Docs samples of criterion 4 do not
 * exist yet. Canary: no payload sets `window.__fe054Canary`, so no script ran during the parse.
 *
 * Runs in real browser engines through `pnpm vitest run --project browser <this file>`
 * (`DOCEDIT_BROWSERS=chromium,firefox,webkit` for all three). Skipped in Node.js, which has no DOM.
 */
import fc from 'fast-check';
import { LINK_HREF_PATTERN } from '@docedit/model/definition';
import { describe, expect, it } from 'vitest';
import { fragmentFromHtmlString } from '../clipboard-html.ts';

const isBrowser = typeof document !== 'undefined' && typeof DOMParser !== 'undefined';

/** Text that may appear in the output. It never contains the word the dropped elements carry. */
const TEXT_WORDS = ['alpha', 'bravo', 'x', '&amp;', '&lt;b&gt;', '&quot;', ' ', ' ', 'café'];

/** Markup pieces. Those with DROPPED in them put that word inside an element the whitelist drops. */
const PIECES = [
  '<p>',
  '</p>',
  '<div>',
  '</div>',
  '<b>',
  '</b>',
  '<i>',
  '</i>',
  '<strong>',
  '</strong>',
  '<em>',
  '</em>',
  '<span>',
  '</span>',
  '<li>',
  '<h1>',
  '</h1>',
  '<table><tr><td>',
  '</td></tr></table>',
  '<br>',
  '<a href="https://example.com/a">',
  '<a href="javascript:window.__fe054Canary=1">',
  '<a href="JAVASCRIPT:alert(1)">',
  '<a href="data:text/html,DROPPED">',
  '<a href="vbscript:DROPPED">',
  '<a href="mailto:a@example.com">',
  '<a href="#target-1">',
  '<a href=" https://example.com/spaced ">',
  '<a href="https://example.com/x" onclick="window.__fe054Canary=2">',
  '</a>',
  '<script>window.__fe054Canary=3; DROPPED</script>',
  '<script src="https://example.invalid/s.js"></script>',
  '<style>p{background:url(https://example.invalid/x)} DROPPED</style>',
  '<iframe src="javascript:window.__fe054Canary=4">DROPPED</iframe>',
  '<frameset><frame src="https://example.invalid/f"></frameset>',
  '<object data="https://example.invalid/o">DROPPED</object>',
  '<embed src="https://example.invalid/e">',
  '<img src="https://example.invalid/i.png" onerror="window.__fe054Canary=5" alt="DROPPED">',
  '<svg onload="window.__fe054Canary=6"><text>DROPPED</text></svg>',
  '<math><mi xlink:href="javascript:window.__fe054Canary=7">DROPPED</mi></math>',
  '<form action="javascript:window.__fe054Canary=8"><input value="DROPPED"></form>',
  '<select><option>DROPPED</option></select>',
  '<textarea>DROPPED</textarea>',
  '<template><p>DROPPED</p></template>',
  // noscript is not marked: in the inert document some engines parse its content as ordinary elements, so
  // its text is then ordinary text that the page would show without script (not a payload).
  '<noscript><p>fallback</p></noscript>',
  '<title>DROPPED</title>',
  '<link rel="stylesheet" href="https://example.invalid/s.css">',
  '<meta http-equiv="refresh" content="0;url=https://example.invalid/">',
  '<p style="background:url(javascript:DROPPED)" class="c" id="i">',
  '<p onclick="window.__fe054Canary=9">',
  '<body onload="window.__fe054Canary=10">',
  '<!-- DROPPED -->',
  '<![CDATA[ DROPPED ]]>',
  '<p>&lt;script&gt;window.__fe054Canary=11&lt;/script&gt;</p>',
];

const WORDS = fc.constantFrom(...TEXT_WORDS);
const PIECE = fc.constantFrom(...PIECES);
const SEGMENT = fc.oneof({ weight: 3, arbitrary: PIECE }, { weight: 2, arbitrary: WORDS });
const HTML = fc.array(SEGMENT, { minLength: 1, maxLength: 40 }).map((parts) => parts.join(''));

const LINK = new RegExp(LINK_HREF_PATTERN);
const ALLOWED_MARKS = new Set(['bold', 'italic', 'link']);

/** The first violation of the model's shape in a fragment, or null when the fragment is clean. */
function shapeViolation(
  fragment: NonNullable<ReturnType<typeof fragmentFromHtmlString>>,
): string | null {
  for (const block of fragment.content) {
    if (block.type !== 'paragraph') return `block ${block.type}`;
    if (Object.keys(block).some((k) => !['type', 'content'].includes(k)))
      return 'paragraph attribute';
    for (const node of block.content ?? []) {
      if (node.type !== 'text') return `inline ${node.type}`;
      if (typeof node.text !== 'string' || node.text === '') return 'empty text node';
      if (Object.keys(node).some((k) => !['type', 'text', 'marks'].includes(k)))
        return 'text attribute';
      for (const mark of node.marks ?? []) {
        if (!ALLOWED_MARKS.has(mark.type)) return `mark ${mark.type}`;
        if (mark.type === 'link') {
          const href = mark.attrs?.['href'];
          if (Object.keys(mark.attrs ?? {}).some((k) => k !== 'href')) return 'link attribute';
          if (typeof href !== 'string' || !LINK.test(href)) return `link target ${String(href)}`;
          if (/^\s|\s$/.test(href)) return 'link target with a space';
        } else if (mark.attrs !== undefined) {
          return `${mark.type} attribute`;
        }
      }
    }
  }
  return null;
}

describe.skipIf(!isBrowser)(
  'FE-054 criterion 7: hostile clipboard HTML through the whitelist',
  () => {
    it('a seeded corpus of hostile HTML yields only the model shapes, and no dropped text or script runs', () => {
      const w = globalThis as { __fe054Canary?: unknown };
      delete w.__fe054Canary;
      fc.assert(
        fc.property(HTML, (html) => {
          const fragment = fragmentFromHtmlString(html, 1);
          if (fragment === null) return true;
          const problem = shapeViolation(fragment);
          if (problem !== null) throw new Error(`${problem} in ${JSON.stringify(html)}`);
          const text = fragment.content
            .flatMap((b) => (b.content ?? []).map((n) => n.text ?? ''))
            .join('');
          expect(text).not.toContain('DROPPED');
          expect(JSON.stringify(fragment)).not.toMatch(
            /javascript:|vbscript:|data:|onerror|onclick|onload/i,
          );
          return true;
        }),
        { seed: 54, numRuns: 300 },
      );
      expect(w.__fe054Canary, 'no payload ran a script').toBeUndefined();
    });

    it('the fixed hostile samples from criterion 7 are all read to the model shapes', () => {
      const samples = [
        '<p>a</p><script>DROPPED</script>',
        '<p onclick="x">b <a href="javascript:DROPPED">c</a></p>',
        '<svg><script>DROPPED</script></svg><p>d</p>',
        '<p><img src=x onerror="window.__fe054Canary=1">e</p>',
        '<iframe srcdoc="<p>DROPPED</p>"></iframe><p>f</p>',
      ];
      for (const html of samples) {
        const fragment = fragmentFromHtmlString(html, 1);
        if (fragment === null) continue;
        expect(shapeViolation(fragment), html).toBeNull();
        expect(JSON.stringify(fragment), html).not.toContain('DROPPED');
      }
      expect((globalThis as { __fe054Canary?: unknown }).__fe054Canary).toBeUndefined();
    });
  },
);
